public static bool Overlap(int startA, int endA, int startB, int endB)
{
    throw new NotImplementedException();
}

solution:
public static bool Overlap(int startA, int endA, int startB, int endB)
{
    return Math.Max(startA, startB) < Math.Min(endA, endB);
}

