public static long[] ClosingBalances(int count, int[] accountIds, int[] changes)
{
    throw new NotImplementedException();
}

solution:
public static long[] ClosingBalances(int count, int[] accountIds, int[] changes)
{
    var balances = new long[count];
    for (int i = 0; i < changes.Length; i++)
        balances[accountIds[i]] += changes[i];
    return balances;
}

