SELECT s.id AS shift_id
FROM #Shifts AS s
ORDER BY s.id;

solution:
SELECT s.id AS shift_id
FROM #Shifts AS s
WHERE s.approved=1 AND NOT EXISTS (
    SELECT 1 FROM #Bills AS b WHERE b.shift_id=s.id AND b.voided=0
)
ORDER BY s.id;
